typedef unsigned int size_t;

extern "C" void arch_free(void *) __asm__("arch_free__FPv");
extern void *stl_free_list[];
__asm__(".equ arch_free__FPv, 0x002AC768");
__asm__(".equ stl_free_list, 0x003E5628");

inline void stl_deallocate(void *p, size_t bytes)
{
    if (bytes > 128) {
        arch_free(p);
    } else if (bytes) {
        unsigned index = ((bytes + 7) / 8) - 1;
        *(void **)p = stl_free_list[index];
        stl_free_list[index] = p;
    }
}

template<class T>
struct vector {
    T *start;
    T *finish;
    T *end_of_storage;

    ~vector()
    {
        for (T *p = start; p < finish; ++p)
            p->~T();
        stl_deallocate(start, (char *)end_of_storage - (char *)start);
    }
};

template<>
vector<unsigned int>::~vector()
{
    stl_deallocate(start, (char *)end_of_storage - (char *)start);
}

